result = [answers[s['number']] for s in sources]
Path('answer.json').write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n')
print(f'answer.json : {len(result)} articles ; {sum(len(a["reference_checks"]) for a in result)} vérifications de cibles actuelles.')
